// Izvuce cist tekst upita i posiljatelja iz Gmail poruke.
// PROPERTY_CONTEXT se popunjava po klijentu prilikom postavljanja.

const PROPERTY_CONTEXT = `
OBJEKT: {{POPUNITI — naziv, lokacija, broj jedinica}}
JEDINICE: {{POPUNITI — npr. A1 (2+2, 55m2), A2 (4+2, 80m2)}}
CIJENE 2026: {{POPUNITI — po sezoni i jedinici}}
MINIMALNI BORAVAK: {{POPUNITI}}
CHECK-IN / CHECK-OUT: {{POPUNITI}}
UKLJUCENO: {{POPUNITI — parking, klima, wifi, posteljina}}
NIJE UKLJUCENO: {{POPUNITI — boravisna pristojba, cisenje}}
TON: {{POPUNITI — npr. srdacan, kratak, bez usklicnika}}
`;

const out = [];

for (const item of $input.all()) {
  const msg = item.json;

  const headers = msg.payload?.headers || [];
  const header = (name) =>
    headers.find((h) => h.name.toLowerCase() === name.toLowerCase())?.value || '';

  const body =
    msg.text ||
    msg.snippet ||
    '';

  out.push({
    json: {
      messageId: msg.id,
      threadId: msg.threadId,
      from: header('From'),
      subject: header('Subject'),
      receivedAt: new Date(Number(msg.internalDate || Date.now())).toISOString(),
      inquiryText: body.slice(0, 6000),
      propertyContext: PROPERTY_CONTEXT,
    },
  });
}

return out;

// Parsira Claudeov JSON odgovor. Nikad ne radi string-matching na
// serijaliziranom inputu — uvijek JSON.parse (escaping se razlikuje).

const out = [];

for (let i = 0; i < $input.all().length; i++) {
  const res = $input.all()[i].json;
  const src = $('Pripremi kontekst').all()[i].json;

  if (res.stop_reason === 'refusal') {
    out.push({ json: { ...src, is_inquiry: false, error: 'refusal', skip: true } });
    continue;
  }

  const textBlock = (res.content || []).find((b) => b.type === 'text');
  if (!textBlock) {
    out.push({ json: { ...src, is_inquiry: false, error: 'no_text_block', skip: true } });
    continue;
  }

  let parsed;
  try {
    parsed = JSON.parse(textBlock.text.trim().replace(/^```(?:json)?|```$/g, '').trim());
  } catch (e) {
    out.push({ json: { ...src, is_inquiry: false, error: 'parse_failed', raw: textBlock.text, skip: true } });
    continue;
  }

  out.push({
    json: {
      ...src,
      ...parsed,
      skip: parsed.is_inquiry !== true,
      usage: res.usage || {},
    },
  });
}

// Propusti dalje samo stvarne upite.
return out.filter((o) => !o.json.skip);
